import { __decorate } from "tslib";
import { Component } from '@angular/core';
/**
 * Page d'accueil une fois connecté : sidebar + SMARK'ET, contenu dans le coin opposé au logo (haut droit).
 */
let HomeComponent = class HomeComponent {
  constructor(auth) {
    this.auth = auth;
    this.currentUser = null;
    this.isLoggedIn = false;
  }
  ngOnInit() {
    this.isLoggedIn = this.auth.isLoggedIn();
    this.currentUser = this.auth.getStoredUser();
  }
  getWelcomeName() {
    if (!this.currentUser) return '';
    const first = this.currentUser.firstName || '';
    const last = this.currentUser.lastName || '';
    return (first + ' ' + last).trim() || this.currentUser.email || 'Utilisateur';
  }
  getRoleLabel() {
    if (!this.currentUser?.role) return '';
    switch (this.currentUser.role) {
      case 'admin':
        return 'Administrateur';
      case 'boutique':
        return 'Boutique';
      case 'acheteur':
        return 'Acheteur';
      default:
        return this.currentUser.role;
    }
  }
};
HomeComponent = __decorate([Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})], HomeComponent);
